"""Reproducible engineering calculations; monetary inputs are budget assumptions."""
from pathlib import Path
import json,csv
root=Path(__file__).resolve().parents[1]
rows=[('ESP32-P4-DevKit module',1,25,40),('AD9708 + THS7314 + 27MHz clock + logic',1,13,26),('CV opamps + TMUX1511 + MCP3204',1,10,19),('MCP23017 x2 + CD74HC4067 x2',1,5,11),('TPS54302 + inductor + protection',1,4,9),('Passive components + LEDs',1,5,12),('24 panel potentiometers',24,1.5,3.5),('2 encoders',2,1.5,4),('8 buttons',8,.2,.8),('TFT module',1,12,23),('Connectors / RCA / CV / ribbon / sockets',1,10,23),('Two four-layer PCBs allocated to one prototype',1,15,35),('SMD assembly / setup allocated to one prototype',1,35,90)]
with (root/'hardware/cost-estimate-usd.csv').open('w') as f:
 w=csv.writer(f);w.writerow(['group','quantity','unit_low_USD','unit_high_USD','line_low_USD','line_high_USD','basis'])
 for n,q,lo,hi in rows:w.writerow([n,q,lo,hi,round(q*lo,2),round(q*hi,2),'planning assumption; NOT a supplier quote'])
cycles=400e6/(720*480*30000/1001)
calc={'video':{'frames_per_second':30000/1001,'fields_per_second':60000/1001,'active_pixels_per_second':720*480*30000/1001,'DAC_samples_per_second':27000000,'line_samples':1716,'line_us':1716/27,'frame_samples':900900,'double_raster_buffer_bytes':1801800,'double_luma_buffer_bytes':691200,'lcd_RGB565_bytes':320*240*2,'loaded_sync_to_white_V':32*1.2/1910*49.9*255/256,'loaded_sync_to_black_V':32*1.2/1910*49.9*73/256},'compute':{'cycles_per_active_pixel_per_400MHz_core':cycles,'oscillator_evaluations_per_second':6*720*480*30000/1001,'route_accumulations_per_second_36':36*720*480*30000/1001,'note':'clock and scheduling reserve depend on actual chip revision; no P4 measurement'},'adc':{'cv_samples_per_channel_s':4000,'pot_scans_per_control_s':100,'total_conversions_per_s_with_discard':2*4000+24*100*2,'spi_1MHz_fraction_at_24_clocks':(8000+4800)*24/1e6,'CV_adc_V_at_zero':1.65*100/104.7},'power_budget':{'assumed_5V_current_A':[.4,.9],'assumed_efficiency':.85,'assumed_input_after_diode_V':11.7,'estimated_12V_current_A':[round(5*i/(.85*11.7),3) for i in [.4,.9]],'not_measured':True},'cost_USD':{'low':round(sum(q*l for _,q,l,h in rows),2),'high':round(sum(q*h for _,q,l,h in rows),2),'excluded':['tax','shipping','front metal panel','24 knobs','manual THT labour','rework','test equipment'],'supplier_quote':False}}
(root/'hardware/verification/r1-calculations.json').write_text(json.dumps(calc,indent=2)+'\n');print(json.dumps(calc,indent=2))
